arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_6730f3fe8518430e87957e25c1131849.Models
@using sv_6730f3fe8518430e87957e25c1131849.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@if (_submitted)
{
    <div class="alert alert-success mt-4">
        <h3>Application Submitted!</h3>
        <p>Your application has been received. Your confirmation number is <strong>#@_applicationId</strong>.</p>
    </div>
}
else
{
    <!-- Step Indicator -->
    <nav class="step-indicator mb-4">
        <ol class="d-flex list-unstyled justify-content-between">
            @for (int i = 0; i < _stepNames.Length; i++)
            {
                var stepIndex = i;
                var isCompleted = stepIndex < _currentStep;
                var isCurrent = stepIndex == _currentStep;
                var isFuture = stepIndex > _currentStep;

                <li class="step-item @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "dimmed" : "")"
                    @onclick="() => GoToStep(stepIndex)"
                    style="cursor: @(isCompleted ? "pointer" : "default"); flex: 1; text-align: center;">
                    <span class="step-badge @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-secondary text-white")"
                          style="display: inline-block; width: 30px; height: 30px; line-height: 30px; border-radius: 50%; font-size: 0.85rem;">
                        @if (isCompleted)
                        {
                            <span>&#10003;</span>
                        }
                        else
                        {
                            @(stepIndex + 1)
                        }
                    </span>
                    <div class="step-label mt-1 small @(isFuture ? "text-muted" : "")">@_stepNames[stepIndex]</div>
                </li>
            }
        </ol>
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger">@_errorMessage</div>
    }

    <!-- Step 1: Personal Info -->
    @if (_currentStep == 0)
    {
        <h3>Personal Information</h3>
        <div class="mb-3">
            <label class="form-label">Full Name *</label>
            <input type="text" class="form-control" @bind="_fullName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email *</label>
            <input type="email" class="form-control" @bind="_email" />
        </div>
        <div class="mb-3">
            <label class="form-label">Phone *</label>
            <input type="tel" class="form-control" @bind="_phone" />
        </div>
        <div class="mb-3">
            <label class="form-label">Address *</label>
            <input type="text" class="form-control" @bind="_address" />
        </div>
        <div class="d-flex justify-content-end">
            <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
                @if (_isValidating)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Next
            </button>
        </div>
    }

    <!-- Step 2: Work History -->
    @if (_currentStep == 1)
    {
        <h3>Work History</h3>
        @for (int i = 0; i < _workEntries.Count; i++)
        {
            var index = i;
            <div class="card mb-3">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h5 class="card-title mb-0">Position @(index + 1)</h5>
                        @if (_workEntries.Count > 1)
                        {
